    /** Video length. */
    durationSeconds: number | null;
    /** Width of the original as seen. */
    width: number | null;
    /** Height of the original as seen. */
    height: number | null;
    /** Upload started. */
    createdAt: string;
    /** Last processed. */
    processedAt: string | null;
    /** The blurred video or photo. */
    previewUrl: string | null;
    /** Its thumbnail. */
